"""Compile editorial source data into the static app. Never reads/bundles EPUBs."""
from pathlib import Path
import hashlib,json
root=Path(__file__).resolve().parents[1]
source=root/'sample-content/sample-content-plan-v2.json'
raw=json.loads(source.read_text());assert raw['schema']=='sample-content-plan-v2-expanded'
ids={'alice':('alice','alice'),'pride':('pride','pride and prejudice'),'dracula':('dracula','dracula'),'trutien':('tru-tien','tru tien'),'thienquan':('thien-quan','thien quan'),'guilt':('guilt','guilt')}
types={'parent_of':'parent','spouse_of':'partner','master_of':'master'}
books=[]
for b in sorted(raw['books'],key=lambda b:b['order']):
 id,match=ids[b['id']];chars=b.get('sample_characters',b['characters']);rels=b.get('sample_relationships',b['relationships']);cards=b.get('sample_cards',b['cards']);trees=b.get('sample_trees',[b['tree']] if b.get('tree') else [])
 cardids=[c.get('id','card-'+str(i)) for i,c in enumerate(cards)]
 normalized=dict(id=id,sourceId=b['id'],match=match,title=b['title'],author=b['author'],color=b['spine'],epubSHA256=b['epub_sha256'],epubSize=b['epub_size_bytes'],filename=b['epub_source_filename'],rights=b['rights'],focus=b['focus'],genre=b['genre'],language=b['language'],characters=[[c['id'],c['name'],c.get('role',c.get('description',''))] for c in chars],characterDetails=chars,relationships=[[r['from_id'],types.get(r['type'],'custom'),r['to_id'],r['type'].replace('_',' ')] for r in rels],relationshipDetails=rels,cards=[[c['title'],c['type'],c.get('body',c.get('description','')),c.get('source',{}).get('href',c.get('source_href')),c.get('source',{}).get('search_hint')] for c in cards],cardDetails=cards,connections=[[cardids.index(c['from_id']),cardids.index(c['to_id']),c['label']] for c in b.get('story_board_connections',[])],trees=[])
 for t in trees:
  ranks=t.get('rank_levels',t.get('ranks',[]));assignment=t.get('rank_assignments',t.get('assignments',{}))
  normalized['trees'].append(dict(id=t.get('id','family'),name=t['name'],template=t['template'],members=t['member_ids'],ranks=ranks,assignments={key:ranks.index(v) for key,v in assignment.items()},description=t.get('notes',t.get('description',''))))
 normalized['highlightPlans']=b.get('sample_highlights',[])
 books.append(normalized)
assert len(books)==6
(root/'dist/sample-plan.js').write_text('/* Generated by scripts/prepare-sample-plan.py. Editorial metadata only; no EPUB bytes. */\nconst SamplePlan='+json.dumps(dict(provenance='sample-content/sample-content-plan-v2.json',revision=hashlib.sha256(source.read_bytes()).hexdigest(),books=books),ensure_ascii=False,indent=2)+';\n')
print([(b['id'],len(b['characters']),len(b['relationships']),len(b['cards']),len(b['connections'])) for b in books])
